def copy_fee_into_version_one(apps, schema_editor):
    """Today's single fee becomes version 1, so the fee customers are charged does not change."""
    old = apps.get_model("rental", "RentalPlatformFee").objects.filter(pk=1).first()
    if old is None:
        return  # No fee was ever set: no version, and still no fee, as before.
    apps.get_model("rental", "RentalPlatformFeeVersion").objects.create(
        version=1,
        percent=old.percent,
        effective_from=old.updated_at,
        approval_reference="Set before fee versioning",
        created_by_id=old.updated_by_id,
    )


def copy_latest_version_back(apps, schema_editor):
    """Reverse: the fee in force now becomes the single fee again."""
    from django.utils import timezone

    latest = (
        apps.get_model("rental", "RentalPlatformFeeVersion")
        .objects.filter(effective_from__lte=timezone.now())
        .order_by("-effective_from")
        .first()
    )
    if latest is None:
        return
    apps.get_model("rental", "RentalPlatformFee").objects.update_or_create(
        pk=1, defaults={"percent": latest.percent, "updated_by_id": latest.created_by_id}
    )


